#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;
const int redPin = 2;    
const int greenPin = 3;  
const int bluePin = 4;   

void setup();
void loop();
void setColor(int red, int green, int blue);
void moveServos(int angle1, int angle2, int angle3);
void setup() {
  pinMode(redPin, OUTPUT);
  pinMode(greenPin, OUTPUT);
  pinMode(bluePin, OUTPUT);
  servo1.attach(5);  
  servo2.attach(6);  
  servo3.attach(7);  
  servo1.write(0);
  servo2.write(90);
  servo3.write(180);
}
void loop() {
  setColor(255, 0, 0);
  moveServos(0, 90, 180);
  delay(2000);
  setColor(0, 255, 0);
  moveServos(90, 180, 0);
  delay(2000);
  setColor(0, 0, 255);
  moveServos(180, 0, 90);
  delay(2000);
  setColor(255, 255, 0);
  moveServos(45, 135, 180);
  delay(2000);
  setColor(0, 255, 255);
  moveServos(135, 180, 45);
  delay(2000);
  setColor(255, 0, 255);
  moveServos(180, 45, 135);
  delay(2000);
  setColor(255, 255, 255);
  moveServos(0, 90, 180);
  delay(2000);
}
void setColor(int red, int green, int blue) {
  analogWrite(redPin, red);
  analogWrite(greenPin, green);
  analogWrite(bluePin, blue);
}
void moveServos(int angle1, int angle2, int angle3) {
  servo1.write(angle1);
  servo2.write(angle2);
  servo3.write(angle3);
}
